<?php require_once __DIR__ . "/../includes/auth-check.php"; require_once __DIR__ . "/../Config/db.php"; require_once __DIR__ . "/../includes/ui.php"; $uid=(int)$_SESSION['user_id']; $reports=$conn->query("SELECT r.*, a.ambulance_name FROM reports r LEFT JOIN ambulance_locations a ON a.id=r.assigned_ambulance_id WHERE r.user_id=$uid ORDER BY r.created_at DESC"); sr_page_start('My Reports','reports'); ?>
<div class="hero-card"><h2>My accident reports</h2><p>Track your submitted cases, AI triage status and ambulance assignment.</p><div class="toolbar" style="margin-top:18px"><a class="btn danger" href="submit-report.php">Submit New Report</a><a class="btn light" href="track-report.php">Track Status</a></div></div>
<div class="card" style="margin-top:18px"><div class="table-wrap"><table><thead><tr><th>ID</th><th>Incident</th><th>AI</th><th>Priority</th><th>Status</th><th>Ambulance</th><th>Created</th><th>Action</th></tr></thead><tbody><?php if($reports && $reports->num_rows): while($r=$reports->fetch_assoc()): ?><tr><td>#<?php echo (int)$r['id']; ?></td><td><strong><?php echo htmlspecialchars($r['title']); ?></strong><br><span class="mini"><?php echo htmlspecialchars($r['location']); ?></span></td><td><?php echo sr_badge($r['ai_verdict']); ?><br><span class="mini"><?php echo (int)$r['ai_score']; ?>/100</span></td><td><?php echo (int)$r['priority_score']; ?>/100</td><td><?php echo sr_badge($r['status']); ?></td><td><?php echo htmlspecialchars($r['ambulance_name'] ?? 'Not assigned'); ?></td><td><?php echo sr_time($r['created_at']); ?></td><td><a class="btn small" href="report-details.php?id=<?php echo (int)$r['id']; ?>">Open</a></td></tr><?php endwhile; else: ?><tr><td colspan="8"><div class="empty-state">No report yet. Create a demo emergency report.</div></td></tr><?php endif; ?></tbody></table></div></div>
